export const money=n=>Number(n).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2});
function readInt(n){if(!n)return '';const digits=['ศูนย์','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'];if(n>=1000000)return readInt(Math.floor(n/1000000))+'ล้าน'+readInt(n%1000000);const s=String(n),places=['','สิบ','ร้อย','พัน','หมื่น','แสน'];return [...s].map((v,i)=>{const d=+v,p=s.length-i-1;if(!d)return '';if(p===1)return(d===1?'':d===2?'ยี่':digits[d])+'สิบ';return(p===0&&d===1&&s.length>1?'เอ็ด':digits[d])+places[p]}).join('')}
export function baht(cents){const b=Math.floor(cents/100),s=cents%100;return(b?readInt(b):'ศูนย์')+'บาท'+(s?readInt(s)+'สตางค์':'ถ้วน')}
export async function documentCanvases(q){await document.fonts.load('20px Sarabun');const pages=[];const chunks=[];for(let i=0;i<q.items.length;i+=14)chunks.push(q.items.slice(i,i+14));for(let page=0;page<chunks.length;page++){const canvas=document.createElement('canvas');canvas.width=1240;canvas.height=1754;const c=canvas.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,1240,1754);c.fillStyle='#111';const text=(s,x,y,size=20,align='left',max=1100)=>{c.font=`${size}px Sarabun`;c.textAlign=align;c.fillText(String(s),x,y,max)};const line=(x,y,x2,y2)=>{c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.stroke()};c.strokeStyle='#171717';c.lineWidth=1.5;
text('ใบเสนอราคา',620,155,28,'center');text(q.company.name,620,192,21,'center');text(q.company.address,620,225,19,'center',1030);text('หมายเลขโทรศัพท์ '+q.company.phone,620,258,19,'center');text('หมายเลขทะเบียน '+q.company.registration,620,291,19,'center');line(543,319,697,319);
text('วันที่ '+new Date(q.date+'T12:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'long',year:'numeric'}),894,403,20,'left',275);text('เลขที่ '+q.number,894,438,20,'left',275);if(q.customer){text('เรียน '+q.customer,104,475,20);if(q.customerAddress)text(q.customerAddress,104,506,18,'left',1030)}
const start=565,head=70,rowH=37,rows=Math.max(6,chunks[page].length),xs=[104,202,514,638,746,946,1136];text('1. รายการซักผ้า',104,start-14,22);xs.forEach(x=>line(x,start,x,start+head+rows*rowH));line(104,start,1136,start);line(104,start+head,1136,start+head);['ลำดับ','รายการ','จำนวน','หน่วย','ราคาต่อหน่วย','จำนวนเงิน'].forEach((v,i)=>text(v,(xs[i]+xs[i+1])/2,start+30,20,'center'));text('(บาท)',846,start+57,19,'center');text('(บาท)',1041,start+57,19,'center');for(let i=0;i<rows;i++){const y=start+head+i*rowH;line(104,y+rowH,1136,y+rowH);const item=chunks[page][i];if(item){const values=[page*14+i+1+'.',item.name,item.qty,item.unit,money(item.price/100),money(item.price*item.qty/100)];values.forEach((v,j)=>text(v,j===1?xs[j]+13:(xs[j]+xs[j+1])/2,y+26,18,j===1?'left':'center',xs[j+1]-xs[j]-20))}}
const y=start+head+rows*rowH;line(104,y+46,1136,y+46);line(104,y,104,y+46);line(746,y,746,y+46);line(946,y,946,y+46);line(1136,y,1136,y+46);const last=page===chunks.length-1;const total=last?q.total:chunks[page].reduce((s,i)=>s+i.qty*i.price,0);text(last?'ตัวอักษร ('+baht(total)+')':'ยอดรวมหน้านี้',116,y+30,18,'left',610);text(last?'รวมเป็นเงินทั้งสิ้น':'รวมหน้านี้',846,y+30,20,'center',184);text(money(total/100),1041,y+30,20,'center',170);text('ขอแสดงความนับถือ',104,y+78,20);const sy=Math.max(y+230,1150);text('ลงชื่อ........................................ผู้รับราคา',104,sy,20,'left',465);text('('+ (q.recipient||'........................................') +')',290,sy+48,20,'center',380);text('ลงชื่อ........................................ผู้เสนอราคา',735,sy,20,'left',440);text('('+q.company.signer+')',938,sy+48,20,'center',410);text('กำหนดยืนราคา '+q.validDays+' วัน / กำหนดส่งสินค้า '+q.deliveryDays+' วัน',104,1510,21);if(q.note)text('หมายเหตุ: '+q.note,104,1555,18,'left',1030);if(pages.length||chunks.length>1)text('หน้า '+(page+1)+' / '+chunks.length,1136,1660,16,'right');pages.push(canvas)}return pages}
export function pdfBlob(canvases){const enc=new TextEncoder();const parts=[];let length=0;const offsets=[0];const append=d=>{const b=typeof d==='string'?enc.encode(d):d;parts.push(b);length+=b.length};const obj=(id,data)=>{offsets[id]=length;append(id+' 0 obj\n');append(data);append('\nendobj\n')};append('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');const kids=canvases.map((_,i)=>(3+i*3)+' 0 R').join(' ');obj(2,'<< /Type /Pages /Kids ['+kids+'] /Count '+canvases.length+' >>');canvases.forEach((cv,i)=>{const id=3+i*3;obj(id,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im ${id+1} 0 R >> >> /Contents ${id+2} 0 R >>`);const bin=atob(cv.toDataURL('image/jpeg',.97).split(',')[1]);const bytes=Uint8Array.from(bin,x=>x.charCodeAt(0));offsets[id+1]=length;append(`${id+1} 0 obj\n<< /Type /XObject /Subtype /Image /Width ${cv.width} /Height ${cv.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length} >>\nstream\n`);append(bytes);append('\nendstream\nendobj\n');const stream='q\n595.28 0 0 841.89 0 0 cm\n/Im Do\nQ\n';obj(id+2,`<< /Length ${enc.encode(stream).length} >>\nstream\n${stream}endstream`)});const xref=length;append('xref\n0 '+offsets.length+'\n0000000000 65535 f \n');for(let i=1;i<offsets.length;i++)append(String(offsets[i]).padStart(10,'0')+' 00000 n \n');append(`trailer\n<< /Size ${offsets.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
